{
  "type": "radar",
  "options": {
    "responsive": true,
    "maintainAspectRatio": false,
    "plugins": {
      "legend": {
        "display": true,
        "position": "top",
        "labels": {
          "usePointStyle": true,
          "padding": 20
        }
      },
      "tooltip": {
        "enabled": true
      }
    },
    "scales": {
      "r": {
        "beginAtZero": true,
        "ticks": {},
        "grid": {},
        "pointLabels": {}
      }
    }
  }
}

{
  "type": "bar",
  "options": {
    "responsive": true,
    "maintainAspectRatio": false,
    "aspectRatio": 0.6,
    "plugins": {
      "legend": {
        "display": true,
        "position": "top",
        "labels": {
          "usePointStyle": true
        }
      },
      "tooltip": {
        "enabled": true
      }
    },
    "scales": {
      "x": {
        "ticks": {
          "font": {
            "weight": 500
          }
        },
        "grid": {
          "display": false,
          "drawBorder": false
        }
      },
      "y": {
        "ticks": {},
        "grid": {
          "drawBorder": false
        }
      }
    }
  }
}
